-- ES/DE/FR translations for all 7 Finland milestones.
-- fi-b2g, fi-en-standard, fi-vida reuse the tracker's own existing
-- translations (i18n/{lang}-data.json) verbatim, per tracker-phrasing-wins.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-early2000s', 'es', 'Finlandia es pionera en formatos nacionales de facturación electrónica', 'Finvoice y TEAPPSXML son anteriores a la mayor parte de la infraestructura europea de facturación electrónica — Finlandia desarrolló una capacidad nacional genuina mucho antes de que existiera cualquier impulso a nivel de la UE.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-early2000s', 'de', 'Finnland ist Vorreiter bei nationalen E-Invoicing-Formaten', 'Finvoice und TEAPPSXML gab es schon vor dem Großteil der europäischen E-Invoicing-Infrastruktur — Finnland baute echte nationale Kapazitäten auf, lange bevor es einen EU-weiten Impuls gab.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-early2000s', 'fr', 'La Finlande fait figure de pionnière avec ses formats nationaux de facturation électronique', 'Finvoice et TEAPPSXML sont antérieurs à la majeure partie de l''infrastructure européenne de facturation électronique — la Finlande a bâti une véritable capacité nationale bien avant toute impulsion au niveau de l''UE.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-act2019', 'es', 'Se aprueba la Ley de Facturación Electrónica 241/2019', 'Establece el derecho legal de las empresas con una facturación superior a 10.000 € a exigir facturas electrónicas de sus proveedores — un derecho legal genuino, pero no un mandato para emitirlas.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-act2019', 'de', 'E-Invoicing-Gesetz 241/2019 verabschiedet', 'Begründet den gesetzlichen Anspruch von Unternehmen mit einem Umsatz über 10.000 €, von ihren Lieferanten E-Rechnungen zu verlangen — ein echtes gesetzliches Recht, aber keine Pflicht, sie auszustellen.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-act2019', 'fr', 'La loi sur la facturation électronique 241/2019 est adoptée', 'Établit le droit légal des entreprises dont le chiffre d''affaires dépasse 10 000 € d''exiger des factures électroniques de leurs fournisseurs — un véritable droit légal, mais pas une obligation de les émettre.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-b2g', 'es', 'Facturación electrónica B2G obligatoria (en vigor desde abril de 2020)', 'Todos los proveedores que facturen a organismos gubernamentales finlandeses deben enviar facturas electrónicas salvo acuerdo en contrario — uno de los regímenes B2G más maduros de Europa, con alrededor del 99% de las facturas a compradores públicos ya electrónicas. Finlandia no tiene un mandato general de facturación electrónica B2B o B2C: la facturación electrónica B2B nacional sigue siendo totalmente voluntaria, aunque las empresas con una facturación superior a 10.000 € tienen el derecho legal de exigir facturas electrónicas a sus proveedores en virtud de la Ley de Facturación Electrónica 241/2019.', '["Si suministra a algún organismo público finlandés, confirme que puede enviar facturas electrónicas — esto lleva siendo la norma durante años, no es un requisito nuevo", "Para el B2B nacional, no asuma que existe un mandato legal — compruebe en su lugar los requisitos contractuales específicos de su cliente"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-b2g', 'de', 'B2G-E-Rechnung verpflichtend (in Kraft seit April 2020)', 'Alle Lieferanten, die finnische Regierungsbehörden in Rechnung stellen, müssen E-Rechnungen senden, sofern nicht anders vereinbart — eines der ausgereiftesten B2G-Regime Europas, mit rund 99 % bereits elektronischer Rechnungen an öffentliche Auftraggeber. Finnland hat keine allgemeine B2B- oder B2C-E-Invoicing-Vorgabe: Die inländische B2B-E-Rechnungsstellung bleibt vollständig freiwillig, obwohl Unternehmen mit einem Umsatz über 10.000 € nach dem E-Invoicing-Gesetz 241/2019 einen gesetzlichen Anspruch haben, E-Rechnungen von ihren Lieferanten zu verlangen.', '["Wenn Sie eine finnische öffentliche Stelle beliefern, bestätigen Sie, dass Sie E-Rechnungen senden können — dies ist seit Jahren die Norm, keine neue Anforderung", "Gehen Sie bei inländischem B2B nicht von einer gesetzlichen Vorgabe aus — prüfen Sie stattdessen die spezifischen vertraglichen Anforderungen Ihres Kunden"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-b2g', 'fr', 'Facturation électronique B2G obligatoire (en vigueur depuis avril 2020)', 'Tous les fournisseurs facturant des organismes gouvernementaux finlandais doivent envoyer des factures électroniques sauf accord contraire — l''un des régimes B2G les plus matures d''Europe, avec environ 99 % des factures aux acheteurs publics déjà électroniques. La Finlande n''a pas d''obligation générale de facturation électronique B2B ou B2C : la facturation électronique B2B nationale reste entièrement volontaire, bien que les entreprises dont le chiffre d''affaires dépasse 10 000 € disposent d''un droit légal d''exiger des factures électroniques de leurs fournisseurs en vertu de la loi sur la facturation électronique 241/2019.', '["Si vous fournissez un organisme public finlandais, confirmez que vous pouvez envoyer des factures électroniques — c''est la norme depuis des années, pas une nouvelle exigence", "Pour le B2B national, ne supposez pas qu''une obligation légale existe — vérifiez plutôt les exigences contractuelles propres à votre client"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-en-standard', 'es', 'El Estado exige facturas electrónicas conformes con EN 16931 (en vigor desde abril de 2021)', 'Desde esta fecha, los organismos gubernamentales finlandeses solo aceptan facturas electrónicas conformes con la Norma Europea (EN 16931) — los formatos no estándar ya no son suficientes para la facturación B2G, aunque la propia facturación electrónica ya llevaba un año siendo obligatoria. Tanto Finvoice 3.0 como TEAPPSXML 3.0 pueden generar facturas conformes con EN, pero el cumplimiento no es automático — las empresas deben verificar que la salida de su software realmente cumple la norma, no asumirlo por defecto.', '["Confirme que la salida de Finvoice 3.0 o TEAPPSXML 3.0 de su software realmente cumple con EN 16931, no solo de forma superficial", "Consulte el directorio Verkkolaskuosoite para confirmar qué operador/portal de facturación electrónica llega a una determinada contraparte del sector público — no existe una única plataforma central"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-en-standard', 'de', 'Staat verlangt EN-16931-konforme E-Rechnungen (in Kraft seit April 2021)', 'Ab diesem Datum akzeptieren finnische Regierungsbehörden nur noch E-Rechnungen, die dem Europäischen Standard (EN 16931) entsprechen — nicht standardisierte Formate reichen für die B2G-Rechnungsstellung nicht mehr aus, obwohl die E-Rechnungsstellung selbst bereits seit einem Jahr verpflichtend war. Sowohl Finvoice 3.0 als auch TEAPPSXML 3.0 können EN-konforme Rechnungen erzeugen, doch die Konformität ist nicht automatisch — Unternehmen müssen prüfen, dass die Ausgabe ihrer Software den Standard tatsächlich erfüllt, statt es standardmäßig anzunehmen.', '["Bestätigen Sie, dass die Finvoice-3.0- oder TEAPPSXML-3.0-Ausgabe Ihrer Software tatsächlich EN-16931-konform ist, nicht nur oberflächlich ähnlich", "Prüfen Sie im Verkkolaskuosoite-Verzeichnis, welcher E-Invoicing-Betreiber/welches Portal eine bestimmte Stelle im öffentlichen Sektor erreicht — es gibt keine einzige zentrale Plattform"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-en-standard', 'fr', 'L''État exige des factures électroniques conformes à l''EN 16931 (en vigueur depuis avril 2021)', 'À partir de cette date, les organismes gouvernementaux finlandais n''acceptent plus que les factures électroniques conformes à la norme européenne (EN 16931) — les formats non standard ne suffisent plus pour la facturation B2G, alors même que la facturation électronique elle-même était déjà obligatoire depuis un an. Finvoice 3.0 et TEAPPSXML 3.0 peuvent tous deux produire des factures conformes à l''EN, mais la conformité n''est pas automatique — les entreprises doivent vérifier que la sortie de leur logiciel respecte réellement la norme, sans la supposer par défaut.', '["Confirmez que la sortie Finvoice 3.0 ou TEAPPSXML 3.0 de votre logiciel est réellement conforme à l''EN 16931, pas seulement superficiellement similaire", "Consultez l''annuaire Verkkolaskuosoite pour confirmer quel opérateur/portail de facturation électronique permet d''atteindre un interlocuteur donné du secteur public — il n''existe pas de plateforme centrale unique"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-peppol-ordering', 'es', 'Se exige Peppol Advanced Ordering para la Administración Central', 'La Administración Central exige ahora específicamente Peppol Advanced Ordering, ampliando la estandarización más allá de la facturación hasta el propio proceso de pedido.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-peppol-ordering', 'de', 'Peppol Advanced Ordering für die Zentralregierung verpflichtend', 'Die Zentralregierung verlangt nun ausdrücklich Peppol Advanced Ordering und weitet die Standardisierung über die Rechnungsstellung hinaus auf den Bestellprozess selbst aus.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-peppol-ordering', 'fr', 'Peppol Advanced Ordering rendu obligatoire pour l''administration centrale', 'L''administration centrale exige désormais spécifiquement Peppol Advanced Ordering, étendant la standardisation au-delà de la facturation jusqu''au processus de commande lui-même.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-vida-prep', 'es', 'El gobierno planea comenzar los preparativos para el ViDA', 'El gobierno finlandés ha indicado que planea comenzar a prepararse para las obligaciones de facturación electrónica B2B intracomunitaria en torno a este año — un indicador orientativo y no vinculante, no una fecha de mandato confirmada.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-vida-prep', 'de', 'Regierung plant Beginn der ViDA-Vorbereitungen', 'Die finnische Regierung hat signalisiert, dass sie um dieses Jahr herum mit den Vorbereitungen auf die innergemeinschaftlichen B2B-E-Invoicing-Pflichten beginnen will — ein weicher, unverbindlicher Anhaltspunkt und kein bestätigtes Vorgabendatum.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-vida-prep', 'fr', 'Le gouvernement prévoit de commencer les préparatifs ViDA', 'Le gouvernement finlandais a indiqué qu''il prévoyait de commencer à se préparer aux obligations de facturation électronique B2B intracommunautaire autour de cette année-là — un simple indicateur non contraignant, et non une date d''obligation confirmée.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-vida', 'es', 'Facturación electrónica B2B intracomunitaria obligatoria bajo el ViDA de la UE', 'Finlandia no tiene actualmente ningún mandato nacional de facturación electrónica B2B, y ninguno está confirmado antes de este plazo a escala de la UE, bajo el cual las transacciones B2B intracomunitarias requerirán facturación electrónica estructurada y reporte digital en todos los Estados miembros. El gobierno finlandés ha indicado que planea comenzar los preparativos alrededor de 2028, y un mandato nacional podría llegar después de este plazo de la UE en lugar de antes — una postura genuinamente diferente a la de la mayoría de los demás países de este seguimiento, que se están adelantando considerablemente al suelo de la UE de 2030.', '["No asuma que Finlandia seguirá el mismo calendario de mandato nacional que sus vecinos nórdicos — a día de hoy, no se ha fijado ninguna fecha de mandato nacional", "Vuelva a consultar esta página periódicamente en lugar de tratar la ausencia actual de mandato como un estado permanente — los preparativos de 2028 podrían revelar un calendario nacional más firme"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-vida', 'de', 'Innergemeinschaftliche B2B-E-Rechnung unter dem EU-ViDA-Rahmen verpflichtend', 'Finnland hat derzeit keine inländische B2B-E-Invoicing-Vorgabe, und keine ist vor dieser EU-weiten Frist bestätigt, unter der innergemeinschaftliche B2B-Transaktionen in jedem Mitgliedstaat strukturierte E-Rechnungen und digitale Meldungen erfordern. Die finnische Regierung hat signalisiert, dass sie Vorbereitungen um 2028 beginnen plant, und eine inländische Vorgabe könnte dieser EU-Frist eher folgen als vorausgehen — eine genuin andere Haltung als bei den meisten anderen EU-Ländern in diesem Tracker, die der EU-Untergrenze von 2030 deutlich vorauseilen.', '["Gehen Sie nicht davon aus, dass Finnland demselben inländischen Vorgaben-Zeitplan wie seine nordischen Nachbarn folgt — bislang wurde kein inländisches Vorgabendatum festgelegt", "Prüfen Sie diese Seite regelmäßig erneut, statt das derzeitige Fehlen einer Vorgabe als dauerhaften Zustand zu behandeln — die Vorbereitungen für 2028 könnten einen konkreteren inländischen Zeitplan zutage fördern"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('fi-vida', 'fr', 'Facturation électronique B2B intracommunautaire obligatoire au titre du ViDA de l''UE', 'La Finlande n''a actuellement aucune obligation nationale de facturation électronique B2B, et aucune n''est confirmée avant cette échéance à l''échelle de l''UE, en vertu de laquelle les transactions B2B intracommunautaires nécessiteront une facturation électronique structurée et une déclaration numérique dans tous les États membres. Le gouvernement finlandais a indiqué qu''il prévoyait de commencer les préparatifs autour de 2028, et une obligation nationale pourrait suivre cette échéance de l''UE plutôt que la précéder — une posture véritablement différente de celle de la plupart des autres pays de l''UE dans ce suivi, qui devancent largement le plancher de l''UE de 2030.', '["Ne supposez pas que la Finlande suivra le même calendrier d''obligation nationale que ses voisins nordiques — à ce jour, aucune date d''obligation nationale n''a été fixée", "Consultez cette page périodiquement plutôt que de considérer l''absence actuelle d''obligation comme un état permanent — les préparatifs de 2028 pourraient faire apparaître un calendrier national plus ferme"]');
